def kth_custom_number(n):
    """返回第 n 个（从 1 开始）同时满足以下条件的正整数：
    ① 数字中包含 7；② 不是素数；③ 十进制各位数字之和是偶数。
    >>> kth_custom_number(1)
    57
    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    count = 0
    num = 1
    while True:
        if '7' in str(num) and not is_prime(num) and sum(int(d) for d in str(num)) % 2 == 0:
            count += 1
            if count == n:
                return num
        num += 1

