def decode_escaped(s: str) -> str:
    stack = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch == '\\':
            if i + 1 < n:
                stack.append(s[i+1])
                i += 2
            else:
                stack.append('\\')
                i += 1
        elif ch.isdigit():
            num = 0
            while i < n and s[i].isdigit():
                num = num * 10 + int(s[i])
                i += 1
            if i < n and s[i] == '[':
                stack.append((num, []))
                i += 1
            else:
                stack.append(str(num))
        elif ch == '[':
            stack.append('[')
            i += 1
        elif ch == ']':
            if stack and isinstance(stack[-1], tuple):
                num, content = stack.pop()
                # 收集直到匹配的括号内容
                temp = []
                while stack and not (isinstance(stack[-1], tuple) and stack[-1][0] == -1):
                    if isinstance(stack[-1], tuple):
                        # 处理嵌套
                        inner_num, inner_content = stack.pop()
                        temp = inner_content * inner_num + temp
                    else:
                        temp = [stack.pop()] + temp
                # 反转temp得到正确顺序
                temp = temp[::-1]
                decoded = ''.join(temp) * num
                stack.append(decoded)
            else:
                stack.append(']')
            i += 1
        else:
            stack.append(ch)
            i += 1
    # 处理栈中剩余内容
    result = []
    for item in stack:
        if isinstance(item, tuple):
            num, content = item
            result.append(''.join(content) * num)
        else:
            result.append(item)
    return ''.join(result)

