def decode_escaped(s: str) -> str:
    stack = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch == '\\' and i + 1 < n:
            stack.append(s[i+1])
            i += 2
        elif ch.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            num = int(s[i:j])
            i = j
            if i < n and s[i] == '[':
                depth = 1
                k = i + 1
                while k < n and depth > 0:
                    if s[k] == '\\' and k + 1 < n:
                        k += 2
                        continue
                    if s[k] == '[':
                        depth += 1
                    elif s[k] == ']':
                        depth -= 1
                    k += 1
                inner = s[i+1:k-1]
                decoded_inner = decode_escaped(inner)
                stack.append(decoded_inner * num)
                i = k
            else:
                stack.append(str(num))
        elif ch == ']':
            stack.append(ch)
            i += 1
        else:
            stack.append(ch)
            i += 1
    return ''.join(stack)

