def same_parity_pair(nums, target):
    """在 nums 中找到两个不同下标的数，二者之和等于 target，
    且两个数的奇偶性相同（同为奇数或同为偶数）。
    返回 (小下标, 大下标)；不存在返回 None。
    >>> same_parity_pair([1, 3, 2, 4], 6)
    (2, 3)  # 2+4=6，同为偶数
    """
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            j = seen[complement]
            if (num % 2) == (complement % 2):
                return (min(i, j), max(i, j))
        seen[num] = i
    return None

