def flatten_skip(data):
    """展平嵌套列表：数字/字符串保留；None 跳过；字典值原样保留（不递归）；
    元组视为列表递归展平。
    >>> flatten_skip([1, [2, None, [3]], {'a': [4]}], )
    [1, 2, 3, {'a': [4]}]
    """
    result = []
    for item in data:
        if item is None:
            continue
        if isinstance(item, (list, tuple)):
            result.extend(flatten_skip(item))
        else:
            result.append(item)
    return result

